# The legacy 8-bit -> raw-float bridge (raw = legacy_uint8 * scale) is NOT here.
# It is a property of the ancient UAVX parameter space, not of this schema, and it
# lives with the original parameter definitions it decodes:
#     UAVXArmQ/originalparameters/legacy_param_scales.csv
# See also UAVXArmQ/wiki/Session_Report_LegacyParamBridge_Oct23.md.

PARAM_BOOT_REQUIRED: set = {
    8, 12, 13, 14, 15, 35, 43, 44, 47, 71, 73, 89,
}

# Reproduces the FC's ParamMetaDigest() over type+cls+boot+label+min+max+scale.
# Tag 58 asked for index 0xFF answers with the FC's own digest: a mismatch means this
# projection is stale, so regenerate it (default_val is outside the digest by design).
PARAM_META_DIGEST: int = 0xC1C0A9C2
